/** Minimum rendered widths, in CSS pixels, from the pack's rules. */
export const MIN_LOCKUP_WIDTH = 80
export const MIN_SYMBOL_WIDTH = 20
/** Below this width the symbol switches to the favicon's thicker-armed geometry. */
export const SMALL_SYMBOL_BELOW = 32

const LOCKUP_VIEWBOX = { x: 0, y: -12.8, width: 448.3, height: 98 }
const SYMBOL_VIEWBOX = { x: 6, y: 20, width: 54, height: 24 }
const SMALL_SYMBOL_VIEWBOX = { x: 10, y: 21, width: 44, height: 22 }

type ViewBox = { x: number; y: number; width: number; height: number }

function viewBoxOf({ x, y, width, height }: ViewBox) {
  return `${x} ${y} ${width} ${height}`
}

/** The mark: a large counterweight, a level arm, a small weight. */
function Mark() {
  return (
    <>
      <circle cx="18" cy="32" r="12" />
      <rect x="18" y="29" width="36" height="6" />
      <circle cx="54" cy="32" r="6" />
    </>
  )
}

/** The favicon's mark: the same balance with a thicker arm, for small sizes. */
function SmallMark() {
  return (
    <>
      <circle cx="21" cy="32" r="11" />
      <rect x="21" y="28" width="26" height="8" />
      <circle cx="47" cy="32" r="7" />
    </>
  )
}

export interface LogoProps {
  variant?: 'lockup' | 'symbol'
  /** Rendered width in CSS pixels, clamped up to the minimum. */
  width: number
  className?: string
}

export function Logo({ variant = 'lockup', width, className }: LogoProps) {
  const min = variant === 'lockup' ? MIN_LOCKUP_WIDTH : MIN_SYMBOL_WIDTH
  const rendered = Math.max(width, min)
  const small = variant === 'symbol' && rendered < SMALL_SYMBOL_BELOW
  const box =
    variant === 'lockup'
      ? LOCKUP_VIEWBOX
      : small
        ? SMALL_SYMBOL_VIEWBOX
        : SYMBOL_VIEWBOX

  return (
    <svg
      role="img"
      aria-label="Heftra"
      viewBox={viewBoxOf(box)}
      width={rendered}
      height={(rendered * box.height) / box.width}
      fill="currentColor"
      data-variant={small ? 'symbol-small' : variant}
      className={cn('shrink-0 text-foreground', className)}
    >
      {variant === 'lockup' ? (
        <>
          <g transform="translate(-13.845 -46.15) scale(2.3075)">
            <Mark />
          </g>
          <path d={WORDMARK_PATH} />
        </>
      ) : small ? (
        <SmallMark />
      ) : (
        <Mark />
      )}
    </svg>
  )
}
